<script setup lang="ts">
import {ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api} from '@/api/client'
const props=defineProps<{mode:'login'|'register'}>()
const router=useRouter(),route=useRoute(),email=ref(''),password=ref(''),nickname=ref(''),busy=ref(false),error=ref('')
async function submit(){busy.value=true;error.value='';try{await api.post(props.mode==='login'?'/api/auth/login':'/api/auth/register',props.mode==='login'?{email:email.value,password:password.value}:{email:email.value,password:password.value,nickname:nickname.value});await router.push(typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/') ? route.query.redirect : '/profile/')}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
</script>
<template><div class="auth-wrap"><div class="auth-card"><span class="eyebrow">WELCOME TO BANXIA</span><h1>{{mode==='login'?'欢迎回来':'创建你的账号'}}</h1><p>{{mode==='login'?'登录后继续参与这里的讨论。':'加入半夏小筑，收藏喜欢的内容并分享想法。'}}</p><form @submit.prevent="submit"><label v-if="mode==='register'"><input v-model="nickname" placeholder="昵称" required maxlength="40"></label><label><input v-model="email" type="email" placeholder="邮箱地址" required autocomplete="email"></label><label><input v-model="password" type="password" placeholder="密码（至少 8 位）" required minlength="8" autocomplete="current-password"></label><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'请稍候...':mode==='login'?'登录':'注册'}} →</button></form><div class="switch">{{mode==='login'?'还没有账号？':'已经有账号？'}} <RouterLink :to="{ path: mode==='login' ? '/register/' : '/login/', query: route.query }">{{mode==='login'?'立即注册':'去登录'}}</RouterLink></div><small>登录状态使用安全 Cookie 保存，不将长期令牌存入 localStorage。</small></div></div></template>
<style scoped>.auth-wrap{min-height:640px;display:grid;place-items:center;padding:50px 20px}.auth-card{width:min(440px,100%);padding:42px;border:1px solid #e9e5f2;border-radius:24px;background:white;box-shadow:0 24px 70px #655b9110}.auth-card h1{margin:14px 0 8px;font-size:30px}.auth-card>p{color:#817d91;font-size:12px}.auth-card form{display:grid;gap:13px;margin-top:25px}.auth-card label{height:48px;padding:14px;border:1px solid #e8e4f0;border-radius:11px}.auth-card input{width:100%;border:0;outline:0;font-size:12px}.auth-card form button{height:48px;border:0;border-radius:11px;background:#8170cc;color:white}.error{color:#c45465;font-size:11px}.switch{margin:22px 0;text-align:center;color:#817d91;font-size:12px}.switch a{color:#7665bd;font-weight:700}.auth-card small{display:block;text-align:center;color:#aaa4b4;font-size:10px;line-height:1.7}</style>
